SET preserve_insertion_order=false; USE memory; SET temp_directory='/nfs/roberts/scratch/pi_csl53/jr2728/duckdb_tmp';
-- Quarterly Data Axle 2019 June: gzip CSV -> raw parquet (names hashed) -> conversion report -> typed parquet.
CREATE OR REPLACE MACRO hn(x) AS CASE WHEN coalesce(trim(x), '') <> '' THEN hash(upper(trim(x))) END;
.timer on
-- Pass 1: single streaming read of the gzip
COPY (
  SELECT * EXCLUDE (First_Name_1, Middle_Name_1, Last_Name_1, First_Name_2, Middle_Name_2, Last_Name_2, First_Name_3, Middle_Name_3, Last_Name_3, First_Name_4, Middle_Name_4, Last_Name_4, First_Name_5, Middle_Name_5, Last_Name_5),
         hn(First_Name_1) fn_1, hn(Last_Name_1) ln_1, hn(First_Name_2) fn_2, hn(Last_Name_2) ln_2, hn(First_Name_3) fn_3, hn(Last_Name_3) ln_3, hn(First_Name_4) fn_4, hn(Last_Name_4) ln_4, hn(First_Name_5) fn_5, hn(Last_Name_5) ln_5
  FROM read_csv('/nfs/roberts/pi/pi_csl53/corelogic/raw_data/dataaxle/quarterly/US_Consumer_5_File_2019_June.csv.gz', all_varchar = true, header = true, ignore_errors = true, store_rejects = true, rejects_limit = 1000000)
) TO '/nfs/roberts/scratch/pi_csl53/jr2728/da_quarterly/raw/da_2019_06_raw.parquet' (FORMAT parquet, COMPRESSION zstd, ROW_GROUP_SIZE 1000000);
COPY (SELECT * FROM reject_errors) TO '/home/jr2728/ptax_explore/hh_strat/out/daq_2019_06_rejects.csv' (HEADER);
COPY (SELECT * FROM reject_scans) TO '/home/jr2728/ptax_explore/hh_strat/out/daq_2019_06_reject_scans.csv' (HEADER);
