-- Pass 2b: typed, sorted parquet
COPY (
  SELECT try_cast(nullif(trim("FamilyID"), '') AS BIGINT) AS family_id, (nullif(trim("DOWNGRADE_REASON_CODE"), '') IS NOT NULL) AS downgrade_reason_code, nullif(nullif(trim("DOWNGRADE_DATE"), ''), '000000') AS downgrade_date, nullif(trim("RECENCY_DATE"), '') AS recency_date, nullif(trim("LOCATION_TYPE"), '') AS location_type, CASE WHEN nullif(trim("PRIMARY_FAMILY_IND"), '') = '1' THEN true WHEN nullif(trim("PRIMARY_FAMILY_IND"), '') = '0' THEN false END AS primary_family_ind, nullif(trim("HOUSEHOLDSTATUS"), '') AS household_status, try_cast(nullif(trim("TRADELINE_COUNT"), '') AS USMALLINT) AS tradeline_count, nullif(trim("HEAD_HH_AGE_CODE"), '') AS head_hh_age_code, try_cast(nullif(trim("LENGTH_OF_RESIDENCE"), '') AS USMALLINT) AS length_of_residence, try_cast(nullif(trim("CHILDRENHHCOUNT"), '') AS USMALLINT) AS children_hh_count, CASE WHEN nullif(trim("CHILDREN_IND"), '') = '1' THEN true WHEN nullif(trim("CHILDREN_IND"), '') = '0' THEN false END AS children_ind, nullif(trim("ADDRESSTYPE"), '') AS address_type, try_cast(nullif(trim("MAILABILITY_SCORE"), '') AS USMALLINT) AS mailability_score, try_cast(nullif(trim("WEALTH_FINDER_SCORE"), '') AS UBIGINT) AS wealth_finder_score, try_cast(nullif(trim("FIND_DIV_1000"), '') AS UBIGINT) * 1000 AS find, try_cast(nullif(trim("OWNER_RENTER_STATUS"), '') AS USMALLINT) AS owner_renter_status, try_cast(nullif(trim("ESTMTD_HOME_VAL_DIV_1000"), '') AS UBIGINT) * 1000 AS estmtd_home_val, try_cast(nullif(trim("MARITAL_STATUS"), '') AS USMALLINT) AS marital_status, try_cast(nullif(trim("PPI_DIV_1000"), '') AS UBIGINT) * 1000 AS ppi, try_cast(nullif(trim("CBSACODE"), '') AS UINTEGER) AS cbsa_code, try_cast(nullif(trim("CBSATYPE"), '') AS USMALLINT) AS cbsa_type, try_cast(nullif(trim("CSACODE"), '') AS UINTEGER) AS csa_code, try_cast(nullif(trim("LOCATIONID"), '') AS UBIGINT) AS location_id, nullif(trim("HOUSE_NUM"), '') AS house_num, nullif(trim("HOUSE_NUM_FRACTION"), '') AS house_num_fraction, nullif(trim("STREET_PRE_DIR"), '') AS street_pre_dir, nullif(trim("STREET_NAME"), '') AS street_name, nullif(trim("STREET_POST_DIR"), '') AS street_post_dir, nullif(trim("STREET_SUFFIX"), '') AS street_suffix, nullif(trim("UNIT_TYPE"), '') AS unit_type, nullif(trim("UNIT_NUM"), '') AS unit_num, nullif(trim("BOX_TYPE"), '') AS box_type, nullif(trim("BOX_NUM"), '') AS box_num, nullif(trim("ROUTE_TYPE"), '') AS route_type, nullif(trim("ROUTE_NUM"), '') AS route_num, nullif(trim("CITY"), '') AS city, nullif(trim("STATE"), '') AS state, try_cast(nullif(trim("ZIP"), '') AS UINTEGER) AS zip, try_cast(nullif(trim("ZIP4"), '') AS UINTEGER) AS zip4, nullif(trim("DPBC"), '') AS dpbc, CASE WHEN nullif(trim("VACANT"), '') = '1' THEN true WHEN nullif(trim("VACANT"), '') = '0' THEN false END AS vacant, CASE WHEN nullif(trim("USPSNOSTATS"), '') = '1' THEN true WHEN nullif(trim("USPSNOSTATS"), '') = '0' THEN false END AS usps_nostats, nullif(try_cast(nullif(trim("GE_LATITUDE_2010"), '') AS DOUBLE), 0) AS ge_latitude_2010, nullif(try_cast(nullif(trim("GE_LONGITUDE_2010"), '') AS DOUBLE), 0) AS ge_longitude_2010, nullif(trim("GE_CENSUS_LEVEL_2010"), '') AS ge_census_level_2010, try_cast(nullif(trim("GE_CENSUS_STATE_2010"), '') AS USMALLINT) AS ge_census_state_2010, try_cast(nullif(trim("GE_ALS_COUNTY_CODE_2010"), '') AS USMALLINT) AS ge_als_county_code_2010, nullif(try_cast(nullif(trim("GE_ALS_CENSUS_TRACT_2010"), '') AS UBIGINT), 0) AS ge_als_census_tract_2010, try_cast(nullif(trim("GE_ALS_CENSUS_BG_2010"), '') AS USMALLINT) AS ge_als_census_bg_2010, try_cast(nullif(trim("title_code"), '') AS USMALLINT) AS title_code, try_cast(nullif(trim("IndividualID_1"), '') AS UBIGINT) AS individual_id_1, nullif(trim("Suffix_Code_1"), '') AS suffix_code_1, nullif(trim("Gender_1"), '') AS gender_1, try_cast(nullif(trim("Age_1"), '') AS USMALLINT) AS age_1, nullif(trim("Ethnicity_Code_1"), '') AS ethnicity_code_1, try_cast(nullif(trim("IndividualID_2"), '') AS UBIGINT) AS individual_id_2, nullif(trim("Suffix_Code_2"), '') AS suffix_code_2, nullif(trim("Gender_2"), '') AS gender_2, try_cast(nullif(trim("Age_2"), '') AS USMALLINT) AS age_2, nullif(trim("Ethnicity_Code_2"), '') AS ethnicity_code_2, try_cast(nullif(trim("IndividualID_3"), '') AS UBIGINT) AS individual_id_3, nullif(trim("Suffix_Code_3"), '') AS suffix_code_3, nullif(trim("Gender_3"), '') AS gender_3, try_cast(nullif(trim("Age_3"), '') AS USMALLINT) AS age_3, nullif(trim("Ethnicity_Code_3"), '') AS ethnicity_code_3, try_cast(nullif(trim("IndividualID_4"), '') AS UBIGINT) AS individual_id_4, nullif(trim("Suffix_Code_4"), '') AS suffix_code_4, nullif(trim("Gender_4"), '') AS gender_4, try_cast(nullif(trim("Age_4"), '') AS USMALLINT) AS age_4, nullif(trim("Ethnicity_Code_4"), '') AS ethnicity_code_4, try_cast(nullif(trim("IndividualID_5"), '') AS UBIGINT) AS individual_id_5, nullif(trim("Suffix_Code_5"), '') AS suffix_code_5, nullif(trim("Gender_5"), '') AS gender_5, try_cast(nullif(trim("Age_5"), '') AS USMALLINT) AS age_5, nullif(trim("Ethnicity_Code_5"), '') AS ethnicity_code_5,
         fn_1, ln_1, fn_2, ln_2, fn_3, ln_3, fn_4, ln_4, fn_5, ln_5,
         CASE WHEN nullif(trim(ADDRESSTYPE),'') = 'S' AND nullif(trim(HOUSE_NUM),'') IS NOT NULL AND nullif(trim(STREET_NAME),'') IS NOT NULL AND try_cast(ZIP AS UINTEGER) IS NOT NULL
              THEN hash(lpad(try_cast(ZIP AS UINTEGER)::VARCHAR, 5, '0'), upper(trim(STREET_NAME)), upper(trim(HOUSE_NUM))) END AS bkey,
         2019::USMALLINT AS file_year, 6::UTINYINT AS file_month, DATE '2019-06-01' AS file_date
  FROM raw
) TO '/nfs/roberts/scratch/pi_csl53/jr2728/da_quarterly/fy=2019/fm=06' (FORMAT parquet, COMPRESSION zstd, ROW_GROUP_SIZE 1000000, PARTITION_BY (state), OVERWRITE_OR_IGNORE true);
-- no global ORDER BY: sorting 183m wide rows took > 1 h and spilled; one file per state gives the same pruning by region
COPY (SELECT count(*) n_rows, count(DISTINCT family_id) n_family_ids, avg((address_type='S')::INT) share_street, avg((primary_family_ind)::INT) share_primary,
             count(bkey) n_bkey, min(recency_date) min_recency, max(recency_date) max_recency, avg(length_of_residence) mean_lor, avg(age_1) mean_age_1
      FROM read_parquet('/nfs/roberts/scratch/pi_csl53/jr2728/da_quarterly/fy=2019/fm=06/*/*.parquet', hive_partitioning = true)) TO '/home/jr2728/ptax_explore/hh_strat/out/daq_2019_06_typed_summary.csv' (HEADER);

